    private static final class Identity implements PackedProviderCacheIdentity {
        private final Object owner;
        private final String key;
        private final AtomicInteger accounts = new AtomicInteger();
        private Identity(Object owner, String key) { this.owner = owner; this.key = new String(key); }
        @Override public boolean equals(Object other) {
            return other instanceof Identity identity && owner == identity.owner && key.equals(identity.key);
        }
        @Override public int hashCode() { return 7; }
        @Override public boolean accountRetainedMemory(RetainedMemoryAccount account) {
            accounts.incrementAndGet();
            if (account.add(this, 48L)) {
                account.add(owner, 16L);
                account.add(key, 40L + 2L * key.length());
                account.add(accounts, 16L);
            }
            return true;
        }
    }

    private record ProbeIdentity(long payloadBytes) implements PackedProviderCacheIdentity {
        @Override public boolean accountRetainedMemory(RetainedMemoryAccount account) {
            account.add(this, payloadBytes);
            return true;
        }
    }
